INSERT INTO setting_template_refs(tenant_id,id,subject,kind,template_key,entity_id) SELECT t.tenant_id,'tref_'||lower(hex(randomblob(12))),'art_exam','courses','c_417e18194164',t.id FROM offer_courses t JOIN tenant_subjects s ON s.tenant_id=t.tenant_id AND s.id=t.subject WHERE t.subject='art_exam' AND t.source='template' AND t.version=1 AND t.name='素描（石膏 / 头像 / 静物）' AND s.pack_version='0.1';
